  }, [])
  const schedule = useCallback(() => {
    cancelAnimationFrame(frame.current)
    frame.current = requestAnimationFrame(update)
  }, [update])

  /** Opens it; `at` puts it at a point (a context menu), `keyboard` skips the animation. It resolves once the panel is
   * placed and visible, so focus can move into it. */
  const show = useCallback((how: { keyboard?: boolean, at?: { x: number, y: number } } = {}) => {
    returnTo.current = document.activeElement instanceof HTMLElement ? document.activeElement : null
    point.current = how.at ?? null
    setInstant(!!how.keyboard)
    setTarget((anchor.current?.closest('dialog[open]') as HTMLElement | null) ?? document.body)
    setPos(p => ({ ...p, placed: false }))
    setOpen(true)
    return new Promise<void>((resolve) => { resolveShown.current = resolve })
  }, [])
  /** Closes it; `refocus` returns focus to what opened it, `keyboard` closes at once. */
  const hide = useCallback((refocus = false, keyboard = false) => {
    if (!openRef.current) return
    setInstant(keyboard)
    setOpen(false)
    if (refocus) (point.current ? returnTo.current : anchor.current ?? returnTo.current)?.focus({ preventScroll: true })
  }, [])
  const toggle = useCallback((how: { keyboard?: boolean } = {}) => {
    if (openRef.current) hide(how.keyboard, how.keyboard)
    else void show(how)
  }, [hide, show])

  // Once the panel is in the page: place it, then let show() resolve after the placed render.
  useEffect(() => {
    if (!open) return
    if (!pos.placed) update()
    else if (resolveShown.current) {
      resolveShown.current()
      resolveShown.current = null
    }
  }, [open, pos.placed, update])

  useEffect(() => {
    if (!open) return
    stack.push(me)
    function onPointerDown(event: PointerEvent) {
      const t = event.target as Node
      if (panel.current?.contains(t) || anchor.current?.contains(t)) return
      hide()
    }
    function onKey(event: KeyboardEvent) {
      if (event.key !== 'Escape' || stack.at(-1) !== me) return
      // A dialog under the panel would take Escape too: it is the panel's.
      event.preventDefault()
      event.stopPropagation()
      hide(true, true)
    }
    if (!opts.current.sticky) document.addEventListener('pointerdown', onPointerDown, true)
    document.addEventListener('keydown', onKey, true)
    window.addEventListener('scroll', schedule, true)
    window.addEventListener('resize', schedule)
    const ro = new ResizeObserver(schedule)
    if (panel.current) ro.observe(panel.current)
    return () => {
      const i = stack.indexOf(me)
      if (i >= 0) stack.splice(i, 1)
      document.removeEventListener('pointerdown', onPointerDown, true)
      document.removeEventListener('keydown', onKey, true)
      window.removeEventListener('scroll', schedule, true)
      window.removeEventListener('resize', schedule)
      cancelAnimationFrame(frame.current)
      ro.disconnect()
    }
  }, [open, hide, schedule, me])

  /** Focus moving to somewhere outside the panel and its anchor closes it (Tab out of a popover). */
  const onFocusOut = useCallback((event: FocusEvent) => {
    const next = event.relatedTarget as Node | null
    if (opts.current.sticky || !next || panel.current?.contains(next) || anchor.current?.contains(next)) return
    hide()
  }, [hide])

  return { open, anchor, panel, instant, target, pos, show, hide, toggle, update, onFocusOut }
}
export type PopoverController = ReturnType<typeof usePopover>

/** Arrow, Home and End keys over a panel's menu rows; Tab closes. For menus drawn in a PopoverPanel. */
export function onMenuRows(event: KeyboardEvent | React.KeyboardEvent, panel: HTMLElement | null, close: (refocus: boolean) => void) {
  const rows = [...(panel?.querySelectorAll<HTMLElement>('[role^="menuitem"]:not([disabled]), [role="option"]:not([aria-disabled="true"])') ?? [])]
  const at = rows.indexOf(document.activeElement as HTMLElement)
  if (event.key === 'ArrowDown' || event.key === 'ArrowUp') {
    event.preventDefault()
    const step = event.key === 'ArrowDown' ? 1 : -1
    rows[(at + step + rows.length) % rows.length]?.focus()
  }
  else if (event.key === 'Home' || event.key === 'End') {
    event.preventDefault()
    ;(event.key === 'Home' ? rows[0] : rows.at(-1))?.focus()
  }
  else if (event.key === 'Tab') close(false)
}

/** The first thing in `root` that takes focus. */
export function firstFocusable(root: HTMLElement | null) {
  return root?.querySelector<HTMLElement>('button:not(:disabled), [href], input:not(:disabled):not([type="hidden"]), select:not(:disabled), textarea:not(:disabled), [tabindex]:not([tabindex="-1"])') ?? null
}

'use client'
import { Children, cloneElement, isValidElement, useLayoutEffect, useRef, useState, type ReactElement, type ReactNode, type Ref } from 'react'
import { flushSync } from 'react-dom'

// Vue's <Transition> and <TransitionGroup> for the React flavor, with the same class names, so a Vue item's CSS
// (.ds-pop-enter-from, .ds-toast-leave-active, .ds-toast-move...) works unchanged:
//
//   <Transition show={open} name="ds-pop">{<div ... />}</Transition>
//   <TransitionGroup name="ds-toast">{toasts.map((t) => <p key={t.id} ... />)}</TransitionGroup>
//
// Entering: <name>-enter-from and -enter-active, then a frame later -enter-to in place of -enter-from, until the
// transition ends. Leaving: the same with -leave-*, and the element stays until it has, then goes in the same task its
// classes come off (flushSync), so it never shows again for a frame. A group also moves the others with <name>-move
// (FLIP), measured once the entering and leaving children have their classes, as Vue's are. `css={false}` skips the classes (Vue's :css="false"); `duration` is Vue's explicit duration
// in ms, a number or { enter, leave }. The child must take a ref (a DOM element) and className.
type Duration = number | { enter: number, leave: number }
type Phase = 'enter' | 'leave'

const ms = (d: Duration | undefined, phase: Phase) => (d === undefined ? undefined : typeof d === 'number' ? d : d[phase])

/** Runs one Vue transition phase on an element and resolves when it has ended. */
export function runTransition(el: HTMLElement, name: string, phase: Phase, duration?: Duration): Promise<void> {
  const from = `${name}-${phase}-from`
  const active = `${name}-${phase}-active`
  const to = `${name}-${phase}-to`
  el.classList.add(from, active)
  return new Promise((resolve) => {
    let done = false
    const finish = () => {
      if (done) return
      done = true
      el.classList.remove(from, active, to)
      el.removeEventListener('transitionend', onEnd)
      el.removeEventListener('animationend', onEnd)
      resolve()
    }
    const onEnd = (event: Event) => { if (event.target === el) finish() }
    requestAnimationFrame(() => requestAnimationFrame(() => {
      el.classList.remove(from)
      el.classList.add(to)
      const explicit = ms(duration, phase)
      if (explicit !== undefined) return void setTimeout(finish, explicit)
      // The longest transition or animation on it, as Vue reads it; none means done now. A scroll-linked animation
      // (the scroll fade: duration auto) is not timed, so it counts as none.
      const cs = getComputedStyle(el)
      const longest = (durations: string, delays: string) => {
        const d = durations.split(',').map(s => (Number.parseFloat(s) || 0) * (s.trim().endsWith('ms') ? 1 : 1000))
        const l = delays.split(',').map(s => (Number.parseFloat(s) || 0) * (s.trim().endsWith('ms') ? 1 : 1000))
        return Math.max(0, ...d.map((x, i) => x + (l[i % l.length] || 0)))
      }
      const total = Math.max(longest(cs.transitionDuration, cs.transitionDelay), longest(cs.animationDuration, cs.animationDelay))
      if (!total) return finish()
      el.addEventListener('transitionend', onEnd)
      el.addEventListener('animationend', onEnd)
      setTimeout(finish, total + 50)
    }))
  })
}

function mergeRefs<T>(...refs: Array<Ref<T> | undefined>) {
  return (node: T) => {
    for (const r of refs) {
      if (typeof r === 'function') r(node)
      else if (r) (r as { current: T }).current = node
    }
  }
}
type Child = ReactElement<{ ref?: Ref<HTMLElement>, className?: string }>

export interface TransitionProps { show: boolean, name: string, css?: boolean, duration?: Duration, appear?: boolean, children: ReactNode }

/** Vue's <Transition> around one element: it enters when `show` turns true and leaves before it unmounts. */
export function Transition({ show, name, css = true, duration, appear, children }: TransitionProps) {
  // Whether the element is in the page: from the render where `show` turns true until its leave has ended.
  const [present, setPresent] = useState(show)
  const el = useRef<HTMLElement | null>(null)
  const was = useRef<boolean | null>(null)
  const last = useRef<ReactNode>(children)
  if (show) last.current = children
  if (show && !present) setPresent(true)
  useLayoutEffect(() => {
    const before = was.current
    was.current = show
    const node = el.current
    if (before === show) return
    if (show) {
      if (node && css && (before !== null || appear)) void runTransition(node, name, 'enter', duration)
    }
    // Gone in the same task its leave classes come off, as Vue removes it, so no frame shows it whole again.
    else if (node && css && before) void runTransition(node, name, 'leave', duration).then(() => { if (!was.current) flushSync(() => setPresent(false)) })
    else setPresent(false)
  }, [show]) // eslint-disable-line react-hooks/exhaustive-deps
  const child = (show ? children : last.current) as Child
  if (!(show || present) || !isValidElement(child)) return null
  return cloneElement(child, { ref: mergeRefs(child.props.ref, (n: HTMLElement | null) => { el.current = n }) })
}

export interface TransitionGroupProps { name: string, children: ReactNode }

/** Vue's <TransitionGroup>: keyed children enter and leave as <Transition> does, and the rest move with <name>-move. */
export function TransitionGroup({ name, children }: TransitionGroupProps) {
  const nodes = useRef(new Map<string, HTMLElement>())
  const rects = useRef(new Map<string, DOMRect>())
  const seen = useRef(new Set<string>())
  const firstRender = useRef(true)
  const current = Children.toArray(children).filter(isValidElement) as Child[]
  const [leaving, setLeaving] = useState<Map<string, { child: Child, index: number }>>(new Map())
  const prev = useRef<Child[]>([])

  // Children that went away stay, leaving, where they were.
  const keys = new Set(current.map(c => c.key!))
  const gone = prev.current.filter(c => !keys.has(c.key!) && !leaving.has(c.key!))
  if (gone.length) {
    const next = new Map(leaving)
    for (const c of gone) next.set(c.key!, { child: c, index: prev.current.indexOf(c) })
    setLeaving(next)
  }
  prev.current = current
  const list = [...current]
  for (const [key, { child, index }] of leaving) if (!keys.has(key)) list.splice(Math.min(index, list.length), 0, child)

  // Before the DOM changes: where every child is now (for the move).
  for (const [key, node] of nodes.current) rects.current.set(key, node.getBoundingClientRect())

  useLayoutEffect(() => {
    // First every entering and leaving child takes its classes, so the measures for the move below see each as Vue does
    // (an entering one at its enter-from, a leaving one out of the flow): measuring first would fix an entering child's
    // style as it is, fully shown, and its transition would start from the end.
    const entered = new Set<string>()
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node) continue
      if (leaving.has(key)) {
        if (!node.classList.contains(`${name}-leave-active`)) {
          // Gone in the same task its leave classes come off, so no frame shows it whole again.
          void runTransition(node, name, 'leave').then(() => flushSync(() => setLeaving((m) => {
            const n = new Map(m)
            n.delete(key)
            return n
          })))
        }
        continue
      }
      if (!seen.current.has(key)) {
        seen.current.add(key)
        entered.add(key)
        if (!firstRender.current) void runTransition(node, name, 'enter')
      }
    }
    // Then the move: from where each stayed child was to where it is.
    for (const c of list) {
      const key = c.key!
      const node = nodes.current.get(key)
      if (!node || leaving.has(key) || entered.has(key)) continue
      const before = rects.current.get(key)
      if (!before) continue
      const after = node.getBoundingClientRect()
      if (before.left !== after.left || before.top !== after.top) {
        node.style.transitionDuration = '0s'
        node.style.transform = `translate(${before.left - after.left}px, ${before.top - after.top}px)`
        void node.offsetWidth
        node.classList.add(`${name}-move`)
        node.style.transitionDuration = ''
        node.style.transform = ''
        const end = () => {
          node.classList.remove(`${name}-move`)
          node.removeEventListener('transitionend', end)
        }
        node.addEventListener('transitionend', end)
      }
    }
    firstRender.current = false
    for (const key of [...seen.current]) if (!list.some(c => c.key === key)) seen.current.delete(key)
  })

  return (
    <>
      {list.map(c => cloneElement(c, {
        key: c.key,
        ref: mergeRefs(c.props.ref, (n: HTMLElement | null) => {
          if (n) nodes.current.set(c.key!, n)
          else nodes.current.delete(c.key!)
        }),
      }))}
    </>
  )
}

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

import { html, nothing, type PropertyValues } from 'lit'
import { followGlow } from '@/lib/glow'
import { DsElement, define, uid } from '@/elements/lib/element'
import { firstFocusable, PopoverController, popoverStyles, type Align, type Side } from '@/elements/lib/popover'
import styles from 'virtual:tw'

// Popover.tsx as <spyglass-popover>: a panel for any content (a short form, a few settings, a note), opened from a
// button: the card's #262626 fill on Black with a hairline and the brand corner. The trigger: a <button
// slot="trigger"> you style yourself (React's triggerClass), or other content in the `trigger` slot, drawn as a small
// secondary button. Opening moves focus to the panel's first control (or the panel); Escape, a press outside or tabbing
// away closes it, and Escape returns focus to the trigger. It flips to the side with room and stays 8px inside the
// viewport, in the top layer. `open` (reflected) with `open-change`; close() closes it.

// Button.tsx's classes for a small secondary button, in its order.
const TRIGGER = 'inline-flex shrink-0 cursor-pointer items-center justify-center rounded-control whitespace-nowrap select-none transition-[background-color,color] duration-160 ease-out relative isolate overflow-hidden before:pointer-events-none before:absolute before:inset-0 before:-z-1 before:bg-[radial-gradient(circle_var(--ds-glow-radius)_at_var(--glow-x,50%)_var(--glow-y,50%),var(--ds-color-action-glow),transparent)] before:opacity-0 before:transition-opacity before:duration-240 before:ease-out hover:not-disabled:before:opacity-100 disabled:cursor-not-allowed disabled:bg-action-disabled disabled:text-action-disabled-fg h-control-sm gap-1.5 type-ui-strong px-3 bg-action-secondary text-action-secondary-fg shadow-[inset_0_0_0_var(--ds-border-hairline)_var(--ds-color-action-secondary-edge)] hover:not-disabled:bg-action-secondary-hover'

/**
 * @summary A panel for any content, opened from a button.
 * @slot - The panel's content.
 * @slot trigger - A <button> to use as the trigger, or the default trigger's content.
 * @fires open-change - It opened or closed (detail.value).
 */
export class Popover extends DsElement {
	static styles = [DsElement.styles, popoverStyles, styles]
	static properties = { label: {}, side: {}, align: {}, width: {}, triggerLabel: { attribute: 'trigger-label' }, open: { type: Boolean, reflect: true } }

	/** The panel's name for assistive tech. */
	label = ''
	side: Side = 'bottom'
	align: Align = 'start'
	width = '288px'
	triggerLabel?: string
	open = false
	private panelId = uid('popover')
	private pop = new PopoverController(this, {
		anchor: () => this.trigger,
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
	})

	private get trigger(): HTMLElement | null {
		return this.querySelector<HTMLElement>(':scope > button[slot="trigger"]') ?? this.renderRoot.querySelector<HTMLElement>('button[data-trigger]')
	}

	/** Closes it; focus returns to the trigger unless refocus is false. */
	close(refocus = true) {
		this.pop.hide(refocus)
	}
	private async show(keyboard = false) {
		await this.pop.show({ keyboard })
		const panel = this.renderRoot.querySelector<HTMLElement>('.ds-pop')
		// Into an element's own control, so a field takes focus as a click gives it (focusing the host selects its text).
		let target = firstFocusable(panel) ?? panel
		while (target?.shadowRoot) {
			const inner = firstFocusable(target.shadowRoot as unknown as Element)
			if (!inner || inner === target) break
			target = inner
		}
		target?.focus({ preventScroll: true })
	}
	// A click from the keyboard has no pointer detail: the panel opens and closes at once.
	private onClick = (event: MouseEvent) => {
		const keyboard = event.detail === 0
		if (this.pop.open) this.pop.hide(keyboard, keyboard)
		else void this.show(keyboard)
	}

	private wired: HTMLElement | null = null
	protected willUpdate(changed: PropertyValues<this>) {
		this.pop.configure({ side: this.side, align: this.align, gap: 8 })
		if (changed.has('open') && this.open !== this.pop.open && changed.get('open') !== undefined) {
			if (this.open) void this.show()
			else this.pop.hide()
		}
	}
	protected updated(changed: PropertyValues<this>) {
		super.updated(changed)
		const own = this.querySelector<HTMLElement>(':scope > button[slot="trigger"]')
		if (own && own !== this.wired) {
			own.addEventListener('click', this.onClick)
			own.setAttribute('aria-haspopup', 'dialog')
			this.wired = own
		}
		if (own) {
			own.setAttribute('aria-expanded', String(this.pop.open))
			if (this.triggerLabel) own.setAttribute('aria-label', this.triggerLabel)
		}
		if (this.open !== this.pop.open) {
			this.open = this.pop.open
			this.emit('open-change', { value: this.open })
		}
	}
	protected firstUpdated(changed: PropertyValues<this>) {
		super.firstUpdated(changed)
		if (this.open) void this.show()
	}

	render() {
		const own = !!this.querySelector(':scope > button[slot="trigger"]')
		const trigger = own
			? html`<slot name="trigger"></slot>`
			: html`<button data-ds="popover" data-trigger type="button" class=${TRIGGER} aria-haspopup="dialog" aria-expanded=${String(this.pop.open)} aria-controls=${this.pop.open ? this.panelId : nothing} aria-label=${this.triggerLabel ?? nothing} @click=${this.onClick} @pointermove=${(event: PointerEvent) => followGlow(event.currentTarget as HTMLElement, event)}><slot name="trigger"></slot></button>`
		const panel = this.pop.rendered
			? html`<div data-ds="popover" id=${this.panelId} popover="manual" class="ds-pop p-4 fade-y" role="dialog" aria-label=${this.label} tabindex="-1" data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style(`width: ${this.width}`)} @focusout=${this.pop.onFocusOut}><slot></slot></div>`
			: nothing
		return html`${trigger}${panel}`
	}
}

define('popover', Popover)

import { html, nothing } from 'lit'
import { DsElement, define } from '@/elements/lib/element'
import { PopoverController, popoverStyles, type Align, type Side } from '@/elements/lib/popover'
import styles from 'virtual:tw'

// PopoverPanel.tsx as <spyglass-popover-panel>: the floating panel every overlay draws, on its own, for overlays of
// your own: the card's #262626 fill with a hairline and the brand corner, no shadow, beside the element named by
// `anchor` (an id), flipped to the side with room and kept 8px inside the viewport, in the top layer. It grows from its
// anchor over 240ms and leaves in 160ms; opened or closed from the keyboard it does neither. `tip` is the tooltip's
// White fill. Set `open` (or call show() and hide()); a press outside, Escape and focus leaving close it. The library's
// own overlays draw the same panel inside their shadow roots (lib/popover.ts).

/**
 * @summary A floating panel beside an anchor.
 * @slot - The panel's content.
 * @fires open-change - It opened or closed (detail.value).
 */
export class PopoverPanel extends DsElement {
	static styles = [DsElement.styles, popoverStyles, styles]
	static properties = { anchor: {}, side: {}, align: {}, tip: { type: Boolean }, open: { type: Boolean, reflect: true }, sticky: { type: Boolean }, matchWidth: { type: Boolean, attribute: 'match-width' } }

	/** The id of the element it sits beside. */
	anchor = ''
	side: Side = 'bottom'
	align: Align = 'start'
	/** The tooltip's White fill, 2px over 160ms. */
	tip = false
	open = false
	/** A press outside or focus leaving keeps it open. */
	sticky = false
	/** At least as wide as its anchor. */
	matchWidth = false
	private pop = new PopoverController(this, {
		anchor: () => (this.anchor ? (this.getRootNode() as Document | ShadowRoot).getElementById(this.anchor) : null),
		panel: () => this.renderRoot.querySelector<HTMLElement>('.ds-pop'),
	})

	show(keyboard = false) {
		return this.pop.show({ keyboard })
	}
	hide(refocus = false, keyboard = false) {
		this.pop.hide(refocus, keyboard)
	}
	protected willUpdate(changed: Map<PropertyKey, unknown>) {
		this.pop.configure({ side: this.side, align: this.align, sticky: this.sticky, matchWidth: this.matchWidth })
		if (changed.has('open') && this.open !== this.pop.open) {
			if (this.open) void this.pop.show()
			else this.pop.hide()
		}
	}
	protected updated() {
		if (this.open !== this.pop.open) {
			this.open = this.pop.open
			this.emit('open-change', { value: this.open })
		}
	}

	render() {
		return this.pop.rendered
			? html`<div data-ds="popover-panel" popover="manual" class=${this.tip ? 'ds-pop' : 'ds-pop fade-y'} ?data-tip=${this.tip} data-side=${this.pop.pos.side} ?data-instant=${this.pop.instant} ?data-placed=${this.pop.pos.placed} style=${this.pop.style()} @focusout=${this.pop.onFocusOut}><slot></slot></div>`
			: nothing
	}
}

define('popover-panel', PopoverPanel)
